import { Group, Mesh, PlaneGeometry, AmbientLight, DirectionalLight, Object3D, Color, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  const cleanupTasks = [];

  /* ---------- BACKDROP ---------- */
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshStandardNodeMaterial();

  // gradient stops
  const stops = (config.gradientStops ||
    (config.visualSpec && config.visualSpec.gradientStops) ||
    []).filter(Boolean);
  const startColor = new Color(stops[0]?.hex || '#0b0b10');
  const endColor = new Color(stops[1]?.hex || '#13131a');
  backdropMat.colorNode = mix(
    vec3(startColor.r, startColor.g, startColor.b),
    vec3(endColor.r, endColor.g, endColor.b),
    uv().y
  );
  backdropMat.roughness = 1;
  backdropMat.metalness = 0;

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);
  cleanupTasks.push(() => {
    backdropGeom.dispose();
    backdropMat.dispose();
  });

  /* ---------- LIGHTS ---------- */
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2.5, 2);
  root.add(keyLight);
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, -2, -2);
  root.add(rimLight);
  cleanupTasks.push(() => {
    ambient.dispose();
    keyLight.dispose();
    rimLight.dispose();
  });

  /* ---------- TEXT ITEMS ---------- */
  const items = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  // Helper to create text mesh
  const createText = (txt, opts) => {
    const txtObj = ctx.fontAtlas.createText(txt, opts);
    // ensure object3D type
    return txtObj;
  };

  // COLORS
  const inkColor = config.ink || (config.visualSpec && config.visualSpec.ink) || '#16161d';
  const paperColor = config.paper || (config.visualSpec && config.visualSpec.paper) || '#e8ecf2';
  const accentColor = config.accent || (config.visualSpec && config.visualSpec.accent) || '#ff2a38';

  /* Hero */
  const heroSpec = (config.typography && config.typography.hero) || {};
  const heroWords = (items.find(i => i.role === 'hero')?.text || 'TIME, MACHINED.').split(' ');
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  const heroZOffsets = [0.12, 0.0, -0.12];
  let cumulativeX = 0;
  heroWords.forEach((word, idx) => {
    const txt = createText(word, {
      fontSize: heroSpec.fontSize || 124,
      color: inkColor,
      align: 'left',
    });
    txt.position.set(cumulativeX, 0, heroZOffsets[idx] || 0);
    // rough centering estimate using word length
    cumulativeX += (word.length * 0.06);
    heroGroup.add(txt);
  });
  root.add(heroGroup);
  cleanupTasks.push(() => {
    heroGroup.traverse(child => {
      if (child instanceof Mesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
  });

  /* Underline */
  const underlineGeom = new PlaneGeometry(2.6, 0.045);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.emissive = new Color(accentColor);
  underlineMat.emissiveIntensity = 1.2;
  underlineMat.roughness = 1;
  underlineMat.metalness = 0;
  const underline = new Mesh(underlineGeom, underlineMat);
  underline.position.set(-1.3, -0.05, 0); // anchored left
  underline.scale.set(0, 1, 1);
  heroGroup.add(underline);
  cleanupTasks.push(() => {
    underlineGeom.dispose();
    underlineMat.dispose();
  });

  /* Subhead */
  const subSpec = (config.typography && config.typography.subhead) || {};
  const subTextItem = items.find(i => i.role === 'subhead');
  const subText = createText(
    subTextItem?.text || 'Every calibre begins as a solid billet.',
    {
      fontSize: subSpec.fontSize || 40,
      color: paperColor,
      align: 'center',
    }
  );
  subText.position.set(0, -0.65, 0);
  root.add(subText);
  cleanupTasks.push(() => {
    subText.traverse(child => {
      if (child instanceof Mesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
  });

  /* Caption */
  const capSpec = (config.typography && config.typography.caption) || {};
  const capItem = items.find(i => i.role === 'caption');
  const caption = createText(
    capItem?.text || 'NOVA ATELIER / CALIBRE PROGRAM',
    {
      fontSize: capSpec.fontSize || 18,
      color: paperColor,
      align: 'center',
      letterSpacing: capSpec.letterSpacing || 0.12,
    }
  );
  caption.position.set(0, 1.15, 0);
  root.add(caption);
  cleanupTasks.push(() => {
    caption.traverse(child => {
      if (child instanceof Mesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
  });

  /* ---------- ANIMATIONS ---------- */
  const masterTL = gsap.timeline({ defaults: { ease: 'power2.out' } });
  // kinetic-text primitive will handle hero entrance
  // underline animation
  masterTL.fromTo(
    underline.scale,
    { x: 0 },
    { x: 1, duration: 0.5, delay: 0.12, ease: 'power2.out' },
    '+=0.12' // starts after last glyph (approx)
  );
  // subhead fade up
  masterTL.fromTo(
    subText.position,
    { y: subText.position.y + 0.2, opacity: 0 },
    { y: subText.position.y, opacity: 1, duration: 0.5, ease: 'power2.out' },
    '-=0.3'
  );
  // caption fade in (simple)
  masterTL.fromTo(
    caption.position,
    { y: caption.position.y + 0.2, opacity: 0 },
    { y: caption.position.y, opacity: 1, duration: 0.5, ease: 'power2.out' },
    '-=0.4'
  );

  cleanupTasks.push(() => masterTL.kill());

  /* ---------- CINEMATIC PRIMITIVES ---------- */
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives || [];
  primitives.forEach(p => {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const target = p.name === 'kinetic-text' ? heroGroup : root;
      const handle = fn(target, p.params || {});
      primitiveHandles.push(handle);
      if (handle.cleanup) {
        cleanupTasks.push(() => handle.cleanup());
      }
    }
  });

  /* ---------- USERDATA ---------- */
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    primitiveHandles.forEach(h => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    cleanupTasks.forEach(fn => {
      try { fn(); } catch (e) { /* ignore */ }
    });
  };

  return root;
}
